```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing securities, derivatives, debt and equity instruments, investment funds, and market participants based on authoritative financial standards and corpus definitions."@en .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has issuer"@en ;
    rdfs:comment "Relates a financial instrument or security to the legal entity that issued it."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isIssuerOf .

fis:isIssuerOf
    a owl:ObjectProperty ;
    rdfs:label "is issuer of"@en ;
    rdfs:comment "Relates a legal entity to the financial instruments it has issued."@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasIssuer .

fis:hasHolder
    a owl:ObjectProperty ;
    rdfs:label "has holder"@en ;
    rdfs:comment "Relates a financial instrument to the investor or creditor holding it."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isHolderOf .

fis:isHolderOf
    a owl:ObjectProperty ;
    rdfs:label "is holder of"@en ;
    rdfs:comment "Relates an entity to the financial instruments it holds."@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasHolder .

fis:hasUnderlying
    a owl:ObjectProperty ;
    rdfs:label "has underlying"@en ;
    rdfs:comment "Relates a derivative contract or fund to the underlying asset, index, rate, or entity from which its value is derived."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Underlying ;
    owl:inverseOf fis:isUnderlyingOf .

fis:isUnderlyingOf
    a owl:ObjectProperty ;
    rdfs:label "is underlying of"@en ;
    rdfs:comment "Relates an underlying asset, index, or entity to the derivative or fund based upon it."@en ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasUnderlying .

fis:hasConversionTarget
    a owl:ObjectProperty ;
    rdfs:label "has conversion target"@en ;
    rdfs:comment "Relates a convertible instrument to the equity security into which it can be converted."@en ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:Stock ;
    owl:inverseOf fis:isConversionTargetOf .

fis:isConversionTargetOf
    a owl:ObjectProperty ;
    rdfs:label "is conversion target of"@en ;
    rdfs:comment "Relates a stock to the convertible instrument that can be converted into it."@en ;
    rdfs:domain fis:Stock ;
    rdfs:range fis:HybridSecurity ;
    owl:inverseOf fis:hasConversionTarget .

fis:hasExchange
    a owl:ObjectProperty ;
    rdfs:label "has exchange"@en ;
    rdfs:comment "Relates an exchange-traded instrument to the organized securities exchange where it is listed or traded."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:SecuritiesExchange ;
    owl:inverseOf fis:isExchangeOf .

fis:isExchangeOf
    a owl:ObjectProperty ;
    rdfs:label "is exchange of"@en ;
    rdfs:comment "Relates a securities exchange to the instruments listed or traded on it."@en ;
    rdfs:domain fis:SecuritiesExchange ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasExchange .

fis:hasClearingHouse
    a owl:ObjectProperty ;
    rdfs:label "has clearing house"@en ;
    rdfs:comment "Relates a cleared financial contract to the clearing house or central counterparty that guarantees and settles it."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:ClearingHouse ;
    owl:inverseOf fis:isClearingHouseOf .

fis:isClearingHouseOf
    a owl:ObjectProperty ;
    rdfs:label "is clearing house of"@en ;
    rdfs:comment "Relates a clearing house or central counterparty to the contracts it clears."@en ;
    rdfs:domain fis:ClearingHouse ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:hasClearingHouse .

fis:hasReferenceEntity
    a owl:ObjectProperty ;
    rdfs:label "has reference entity"@en ;
    rdfs:comment "Relates a credit default swap or credit derivative to the obligor whose credit risk is transferred."@en ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf isReferenceEntityOf .

fis:isReferenceEntityOf
    a owl:ObjectProperty ;
    rdfs:label "is reference entity of"@en ;
    rdfs:comment "Relates a legal entity to credit default swaps referencing its credit events."@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:CreditDefaultSwap ;
    owl:inverseOf fis:hasReferenceEntity .

fis:hasCollateral
    a owl:ObjectProperty ;
    rdfs:label "has collateral"@en ;
    rdfs:comment "Relates a secured debt obligation to the assets pledged as security."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:Underlying ;
    owl:inverseOf fis:isCollateralOf .

fis:isCollateralOf
    a owl:ObjectProperty ;
    rdfs:label "is collateral of"@en ;
    rdfs:comment "Relates an asset to the debt securities that it collateralizes."@en ;
    rdfs:domain fis:Underlying ;
    rdfs:range fis:DebtSecurity ;
    owl:inverseOf fis:hasCollateral .

#################################################################
#    Data Properties
#################################################################

fis:hasMaturityDate
    a owl:DatatypeProperty ;
    rdfs:label "has maturity date"@en ;
    rdfs:comment "The date on which the principal of a debt security is due to be repaid."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date .

fis:hasExpirationDate
    a owl:DatatypeProperty ;
    rdfs:label "has expiration date"@en ;
    rdfs:comment "The date on which a derivative contract expires or can last be exercised."@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:date .

fis:hasParValue
    a owl:DatatypeProperty ;
    rdfs:label "has par value"@en ;
    rdfs:comment "The nominal, face, or stated principal amount of a security."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasCouponRate
    a owl:DatatypeProperty ;
    rdfs:label "has coupon rate"@en ;
    rdfs:comment "The annual interest rate stated on a debt security."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasStrikePrice
    a owl:DatatypeProperty ;
    rdfs:label "has strike price"@en ;
    rdfs:comment "The predetermined price at which the holder of an option may buy or sell the underlying asset."@en ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasNotionalAmount
    a owl:DatatypeProperty ;
    rdfs:label "has notional amount"@en ;
    rdfs:comment "The reference monetary amount used to calculate payments in derivative contracts such as swaps."@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:decimal .

fis:hasInternationalSecuritiesIdentificationNumber
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has international securities identification number"@en ;
    rdfs:comment "A 12-character alphanumeric code that uniquely identifies a specific security issue."@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string .

fis:hasVotingRightStatus
    a owl:DatatypeProperty ;
    rdfs:label "has voting right status"@en ;
    rdfs:comment "Indicates whether the share confers voting rights on corporate governance decisions."@en ;
    rdfs:domain fis:Stock ;
    rdfs:range xsd:boolean .

#################################################################
#    Top-Level Entities & Taxonomy
#################################################################

fis:LegalEntity
    a owl:Class ;
    rdfs:label "Legal Entity"@en ;
    rdfs:comment "An entity capable of entering contracts, issuing securities, incurring liabilities, or holding assets."@en .

fis:Corporation
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Corporation"@en ;
    rdfs:comment "A commercial or industrial business enterprise incorporated under corporate law."@en .

fis:Government
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Government"@en ;
    rdfs:comment "A governing body of a nation, state, municipality, or local administrative division."@en .

fis:SovereignGovernment
    a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Sovereign Government"@en ;
    rdfs:comment "The national government of a sovereign nation state."@en .

fis:SubSovereignGovernment
    a owl:Class ;
    rdfs:subClassOf fis:Government ;
    rdfs:label "Sub-Sovereign Government"@en ;
    rdfs:comment "A regional, state, provincial, municipal, or local governmental unit."@en .

fis:SupranationalOrganization
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Supranational Organization"@en ;
    rdfs:comment "An international organization established by multiple sovereign nations, such as the World Bank or IMF."@en .

fis:FinancialInstitution
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Financial Institution"@en ;
    rdfs:comment "An institution providing financial services, such as a commercial bank, investment bank, or broker-dealer."@en .

fis:SecuritiesExchange
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Securities Exchange"@en ;
    rdfs:comment "An organized, officially recognized facility where securities or derivatives are listed and traded."@en .

fis:ClearingHouse
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstitution ;
    rdfs:label "Clearing House"@en ;
    rdfs:comment "A central counterparty that interposes itself between buyers and sellers to guarantee trade settlement."@en .

fis:Underlying
    a owl:Class ;
    rdfs:label "Underlying"@en ;
    rdfs:comment "The reference asset, basket, rate, index, or event upon which derivative contracts or structured instruments are based."@en .

#################################################################
#    Financial Instruments & Securities
#################################################################

fis:FinancialInstrument
    a owl:Class ;
    rdfs:subClassOf fis:Underlying ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:comment "A monetary contract between parties that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity (IAS 32)."@en .

fis:CashInstrument
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "Cash Instrument"@en ;
    rdfs:comment "A financial instrument whose value is determined directly by the markets, including securities and transferable loans or deposits."@en .

fis:Security
    a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "Security"@en ;
    rdfs:comment "A negotiable financial asset or instrument representing an investment claim on an issuer that can be traded in financial markets. Jurisdictional conflict: In the US and broadly, securities encompass debt, equity, and derivatives; in the UK and European statutory contexts, the term often specifically applies to equity and fixed income instruments, with derivatives and warrants having distinct treatment."@en .

fis:Derivative
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:FinancialInstrument
            [ a owl:Restriction ;
              owl:onProperty fis:hasUnderlying ;
              owl:someValuesFrom fis:Underlying
            ]
        )
    ] ;
    rdfs:label "Derivative"@en ;
    rdfs:comment "A financial contract whose value depends on the performance of one or more underlying entities, assets, indices, rates, or credit events. BIS taxonomy categorizes derivatives into forwards, swaps, and options (with futures treated as standardized exchange-traded forwards), whereas common market taxonomy categorizes forwards, futures, options, and swaps as four distinct types."@en .

#################################################################
#    Securities Subclasses: Debt, Equity, Hybrid, Fund
#################################################################

fis:DebtSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security"@en ;
    rdfs:comment "A negotiable security serving as evidence of a debt obligation under which the issuer promises to repay principal and make interest payments."@en .

fis:EquitySecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security"@en ;
    rdfs:comment "A negotiable security representing a fractional share of ownership interest in the residual value and control of an entity."@en .

fis:HybridSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:comment "A security combining characteristics of both debt and equity securities. Note: Under accounting standard IAS 32, compound instruments must be split into liability and equity components, diverging from market convention."@en .

fis:InvestmentFund
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Investment Fund"@en ;
    rdfs:comment "A collective investment vehicle that pools capital from multiple investors to invest in a diversified portfolio of securities and other assets."@en .

fis:DepositaryReceipt
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Depositary Receipt"@en ;
    rdfs:comment "A negotiable certificate issued by a bank representing shares in a foreign company traded on a local exchange."@en .

#################################################################
#    Debt Securities Hierarchy & Family
#################################################################

fis:Bond
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond"@en ;
    rdfs:comment "A debt security, generally with a maturity of at least one year, under which the issuer owes a debt to the holder and commits to repay principal at maturity, typically with coupon interest."@en .

fis:CommercialPaper
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Commercial Paper"@en ;
    rdfs:comment "A short-term unsecured promissory note issued by corporations to finance short-term operational liabilities, typically maturing in 270 days or fewer."@en .

fis:CertificateOfDeposit
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Certificate of Deposit"@en ;
    rdfs:comment "A time deposit debt instrument issued by banks and depository institutions with a specified term and interest rate."@en .

fis:Debenture
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Debenture"@en ;
    rdfs:comment "An unsecured long-term debt instrument backed only by the general creditworthiness and reputation of the issuer."@en .

fis:Note
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Note"@en ;
    rdfs:comment "A debt security with an intermediate maturity, typically between one and ten years."@en .

# Bond Specializations by Issuer
fis:CorporateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:Corporation
            ]
        )
    ] ;
    rdfs:label "Corporate Bond"@en ;
    rdfs:comment "A bond issued by a corporation to raise capital for business financing."@en .

fis:GovernmentBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:SovereignGovernment
            ]
        )
    ] ;
    rdfs:label "Government Bond"@en ;
    rdfs:comment "A debt security issued by a sovereign national government to finance public expenditure."@en .

fis:MunicipalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:SubSovereignGovernment
            ]
        )
    ] ;
    rdfs:label "Municipal Bond"@en ;
    rdfs:comment "A bond issued by a local, state, provincial, or municipal governmental body."@en .

fis:SupranationalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasIssuer ;
              owl:someValuesFrom fis:SupranationalOrganization
            ]
        )
    ] ;
    rdfs:label "Supranational Bond"@en ;
    rdfs:comment "A bond issued by an international organization formed by two or more central governments."@en .

# Bond Specializations by Structure & Backing
fis:AssetBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Asset-Backed Security"@en ;
    rdfs:comment "A bond or debt security whose value and cash flows are collateralized by and derived from a discrete pool of underlying financial assets."@en .

fis:MortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Mortgage-Backed Security"@en ;
    rdfs:comment "An asset-backed security secured by a pool of residential or commercial mortgage loans."@en .

fis:ResidentialMortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Residential Mortgage-Backed Security"@en ;
    rdfs:comment "A mortgage-backed security secured by mortgage loans on residential properties."@en .

fis:CommercialMortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Commercial Mortgage-Backed Security"@en ;
    rdfs:comment "A mortgage-backed security secured by mortgage loans on commercial properties."@en .

fis:CollateralizedMortgageObligation
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation"@en ;
    rdfs:comment "A complex mortgage-backed security structured into multi-class tranches with distinct priorities and maturities."@en .

fis:CollateralizedDebtObligation
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation"@en ;
    rdfs:comment "A structured asset-backed security backed by a pool of fixed income debt instruments, bonds, or loans, divided into risk tranches."@en .

fis:CoveredBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Covered Bond"@en ;
    rdfs:comment "A debt instrument backed by public-sector assets or mortgages that remain on the issuing institution's balance sheet."@en .

fis:ZeroCouponBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Zero-Coupon Bond"@en ;
    rdfs:comment "A bond issued at a deep discount that makes no periodic interest payments and pays full par value at maturity."@en .

fis:FixedRateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond"@en ;
    rdfs:comment "A bond that pays a constant, predetermined interest rate (coupon) throughout its term."@en .

fis:FloatingRateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Bond"@en ;
    rdfs:comment "A bond or note whose interest coupon varies periodically based on an external reference benchmark rate."@en .

fis:InflationIndexedBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Inflation-Indexed Bond"@en ;
    rdfs:comment "A bond whose principal and/or interest payments are adjusted relative to a consumer price inflation index."@en .

fis:CallableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Callable Bond"@en ;
    rdfs:comment "A bond with an embedded call option granting the issuer the right to redeem the bond prior to scheduled maturity."@en .

fis:PutableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Putable Bond"@en ;
    rdfs:comment "A bond with an embedded put option giving the holder the right to force early redemption by the issuer."@en .

fis:ConvertibleBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ;
              owl:onProperty fis:hasConversionTarget ;
              owl:someValuesFrom fis:Stock
            ]
        )
    ] ;
    rdfs:label "Convertible Bond"@en ;
    rdfs:comment "A bond that can be converted into a specified number of common shares of the issuing company."@en .

#################################################################
#    Equity Securities Hierarchy
#################################################################

fis:Stock
    a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Stock"@en ;
    rdfs:comment "Capital stock representing fractional ownership of a corporation."@en .

fis:CommonStock
    a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "Common Stock"@en ;
    rdfs:comment "Ordinary equity capital giving holders voting rights and residual claims to corporate earnings and assets."@en .

fis:PreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:label "Preferred Stock"@en ;
    rdfs:comment "A hybrid equity class entitled to dividend payments and liquidation proceeds prior to common stockholders. Note: Under IAS 32, preference shares with mandatory redemption features are classified as liabilities."@en .

fis:CumulativePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock"@en ;
    rdfs:comment "Preferred stock where any omitted dividend payments accumulate in arrears and must be paid before common stock dividends."@en .

fis:NoncumulativePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Noncumulative Preferred Stock"@en ;
    rdfs:comment "Preferred stock where omitted dividends are forfeited and do not accumulate in arrears."@en .

fis:ConvertiblePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:PreferredStock
            [ a owl:Restriction ;
              owl:onProperty fis:hasConversionTarget ;
              owl:someValuesFrom fis:Stock
            ]
        )
    ] ;
    rdfs:label "Convertible Preferred Stock"@en ;
    rdfs:comment "Preferred shares that provide the holder the option to exchange them for common stock."@en .

#################################################################
#    Investment Funds Hierarchy
#################################################################

fis:MutualFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund"@en ;
    rdfs:comment "An open-end investment company pooling funds to purchase securities, transacting exclusively at net asset value."@en .

fis:ExchangeTradedFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:InvestmentFund
            [ a owl:Restriction ;
              owl:onProperty fis:hasExchange ;
              owl:someValuesFrom fis:SecuritiesExchange
            ]
        )
    ] ;
    rdfs:label "Exchange-Traded Fund"@en ;
    rdfs:comment "An investment fund holding a portfolio of assets whose shares are traded continuously on securities exchanges."@en .

#################################################################
#    Derivatives Hierarchy
#################################################################

fis:Forward
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Forward"@en ;
    rdfs:comment "A customized bilateral over-the-counter contract to purchase or sell an asset at a set price on a future date."@en .

fis:Future
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Derivative
            [ a owl:Restriction ;
              owl:onProperty fis:hasExchange ;
              owl:someValuesFrom fis:SecuritiesExchange
            ]
            [ a owl:Restriction ;
              owl:onProperty fis:hasClearingHouse ;
              owl:someValuesFrom fis:ClearingHouse
            ]
        )
    ] ;
    rdfs:label "Future"@en ;
    rdfs:comment "A standardized contract traded on an exchange and settled via a clearing house to buy or sell an asset at a predetermined price on a future delivery date."@en .

fis:StockFuture
    a owl:Class ;
    rdfs:subClassOf fis:Future ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Future
            [ a owl:Restriction ;
              owl:onProperty fis:hasUnderlying ;
              owl:someValuesFrom fis:Stock
            ]
        )
    ] ;
    rdfs:label "Stock Future"@en ;
    rdfs:comment "A futures contract whose underlying reference is an individual firm's stock or a stock index."@en .

fis:Option
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option"@en ;
    rdfs:comment "A contract conveying the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date."@en .

fis:CallOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option"@en ;
    rdfs:comment "An option granting the buyer the right to buy the underlying asset at the strike price."@en .

fis:PutOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option"@en ;
    rdfs:comment "An option granting the buyer the right to sell the underlying asset at the strike price."@en .

fis:AmericanOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option"@en ;
    rdfs:comment "An option that can be exercised on any trading business day on or before its expiration date."@en .

fis:EuropeanOption
    a owl:Class ;
